for _, row in ipairs( MC.GeneratedItemDefinitions ) do
	local registered, err = MC.RegisterItem( {
		name = row[1], maxStack = row[2], maxDamage = row[3], block = row[4],
		texture = row[5], displayName = row[6], rarity = row[7], kind = row[8], model = row[9],
		source = MC.GeneratedItemSourceVersion,
	} )
	if not registered and err ~= "duplicate_item" then
		local message = "[MC] generated item registration failed: " .. tostring( row[1] ) .. " (" .. tostring( err ) .. ")\n"
		if ErrorNoHalt then ErrorNoHalt( message ) else print( message ) end
	end
end
